from cr_common import T, EST

MAP_NOTE = T('ATT&CK and CWE links: analyst mapping for the teaching case — validation required.',
             'Liens ATT&CK et CWE : correspondance établie par l’analyste pour le cas pédagogique — validation requise.')


def P(v, qual, rat, ev, conf):
    """One parameter; a low-confidence value carries the estimate marker."""
    if conf == 'Low':
        rat = (rat[0] + ' ' + EST[0] + '.', rat[1] + ' ' + EST[1] + '.')
    return {'v': v, 'qual': qual, 'rat': rat, 'ev': ev, 'conf': conf}


def CONS(c, i, a, o, f, r, rep, s):
    return {'Confidentiality/privacy': c, 'Integrity': i, 'Availability': a, 'Operations': o, 'Financial': f,
            'Regulatory': r, 'Reputation': rep, 'Safety': s}


